query:
query getBinaryInsights($filters: BinaryInsightsInput!) {
	binaryInsights(filters: $filters) {
		resultCode
		binaryInsights {
			attributes {
				dmUri
				value
			}
			tenant_device_count
			issue_type
			insight_type
			root_metric_value
			group_metric_value
			tenant_metric_value
			rec_binary_version
			rec_upgrade
			rec_tenant_metric_improvement
		}
	}
}
